// Очередь разметки: следующие N товаров, у которых пусто хоть одно из
// метаполей artmellio.style / material / room / palette. Только чтение.
const N = 20;
const token = $input.first().json.access_token;
const url = 'https://kmfmxn-r4.myshopify.com/admin/api/2026-07/graphql.json';
const query = `query($cursor: String) {
  products(first: 100, after: $cursor, query: "status:active OR status:draft", sortKey: TITLE) {
    pageInfo { hasNextPage endCursor }
    nodes {
      id title status
      style: metafield(namespace: "artmellio", key: "style") { value }
      material: metafield(namespace: "artmellio", key: "material") { value }
      room: metafield(namespace: "artmellio", key: "room") { value }
      palette: metafield(namespace: "artmellio", key: "palette") { value }
    }
  }
}`;
const empty = (v) => !v || !v.value || String(v.value).trim() === '' || String(v.value).trim() === '[]';
const NAMES = { style: 'стиль', material: 'материал', room: 'комната', palette: 'палитра' };

const all = [];
let cursor = null;
let pages = 0;
do {
  const r = await this.helpers.httpRequest({
    method: 'POST', url,
    headers: { 'X-Shopify-Access-Token': token, 'Content-Type': 'application/json' },
    body: { query, variables: { cursor } }, json: true,
  });
  if (r.errors) throw new Error('Shopify: ' + JSON.stringify(r.errors));
  const page = r.data.products;
  all.push(...page.nodes);
  cursor = page.pageInfo.hasNextPage ? page.pageInfo.endCursor : null;
  pages += 1;
} while (cursor && pages < 100);

const todo = [];
for (const p of all) {
  const missing = Object.keys(NAMES).filter((k) => empty(p[k])).map((k) => NAMES[k]);
  if (missing.length) todo.push({ p, missing });
}

const список = todo.slice(0, N).map(({ p, missing }, i) => ({
  '№': i + 1,
  товар: p.title,
  статус: p.status === 'ACTIVE' ? 'активен' : 'черновик',
  не_хватает: missing.join(', '),
  открыть: 'https://admin.shopify.com/store/kmfmxn-r4/products/' + p.id.split('/').pop(),
}));

return [{ json: {
  всего_товаров: all.length,
  осталось_разметить: todo.length,
  готово: all.length - todo.length,
  список,
} }];
